```bash
cat <<'EOF' > check_len_implementation.py
from collections.abc import MutableMapping
from bottle import MultiDict

# Check what the default MutableMapping.__len__ does
class TestDict(MutableMapping):
    def __init__(self):
        self.data = {}

    def __getitem__(self, key):
        return self.data[key]

    def __setitem__(self, key, value):
        self.data[key] = value

    def __delitem__(self, key):
        del self.data[key]

    def __iter__(self):
        return iter(self.data)

    def __len__(self):
        # This is what MutableMapping.__len__ does by default
        return len(list(self.keys()))

    def keys(self):
        return self.data.keys()

t = TestDict()
t['a'] = 1
t['b'] = 2
print(f"TestDict len: {len(t)}")  # Uses our __len__ implementation

# Now check MultiDict
m = MultiDict(a=1, b=2)
print(f"MultiDict len: {len(m)}")
print(f"MultiDict keys: {list(m.keys())}")

# Let's also check what list(m.keys()) gives us
print(f"list(m.keys()): {list(m.keys())}")
print(f"len(list(m.keys())): {len(list(m.keys()))}")
EOF
```

